export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const FIRST_INSURANCE_RATE = 0.1;
const PROCESSING_FEE = 5;
const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  if (runeCount === RUNE_BLOCK_SIZE) return RUNE_BLOCK_PREMIUM;
  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type], 0);
};

const calculateQuotePremium = (items: QuoteItem[]): number => {
  const policyBasePremium = calculatePolicyBasePremium(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: calculateQuotePremium(quoteStep.items) }] };
};

