export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const PROCESSING_FEE = 5;
const ALIKE_BLOCK_SIZE = 3;
const ALIKE_BLOCK_PREMIUM = 60;

const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  return countsByType;
};

const premiumForAlikeGroup = (type: string, count: number): number => {
  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
  return formsExactlyOneBlock
    ? ALIKE_BLOCK_PREMIUM
    : count * ITEM_BASE_PREMIUMS[type];
};

const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
  let total = 0;
  for (const [type, count] of countItemsByType(items)) {
    total += premiumForAlikeGroup(type, count);
  }
  return total;
};

const itemSurcharge = (
  items: QuoteItem[],
  applies: (item: QuoteItem) => boolean,
  rate: number,
): number =>
  items.reduce(
    (sum, item) =>
      applies(item) ? sum + ITEM_BASE_PREMIUMS[item.type] * rate : sum,
    0,
  );

const calculateCurseSurcharge = (items: QuoteItem[]): number =>
  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);

const calculateHighEnchantmentSurcharge = (items: QuoteItem[]): number =>
  itemSurcharge(
    items,
    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    HIGH_ENCHANTMENT_SURCHARGE_RATE,
  );

const calculateQuotePremium = (items: QuoteItem[]): number => {
  const policyBasePremium = calculatePolicyBasePremium(items);
  const curseSurcharge = calculateCurseSurcharge(items);
  const highEnchantmentSurcharge = calculateHighEnchantmentSurcharge(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
  return Math.ceil(
    policyBasePremium +
      curseSurcharge +
      highEnchantmentSurcharge +
      firstInsuranceSurcharge +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: calculateQuotePremium(quoteStep.items) }] };
};

