      const { results } = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword", enchantment: 4 }] }],
      });
      expect(results).toEqual([{ premium: 115 }]);
    });
    it("cursed sword with enchantment 4 → only curse surcharge applies → premium 165 G", () => {
      const { results } = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword", enchantment: 4, cursed: true }] },
        ],
      });
      expect(results).toEqual([{ premium: 165 }]);
    });
    it("cursed sword with enchantment 5 → both surcharges apply → premium 195 G (100 + 50 + 30 + 10 + 5)", () => {
      const { results } = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword", enchantment: 5, cursed: true }] },
        ],
      });
      expect(results).toEqual([{ premium: 195 }]);
    });
    it("customer with exactly 2 years with MHPCO → loyalty discount applies: sword → premium 95 G (100 − 20 loyalty + 10 first insurance + 5 fee)", () => {
      const { results } = runScenario({
        customer: { yearsWithMHPCO: 2 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });
      expect(results).toEqual([{ premium: 95 }]);
    });
    it.todo("modifier scope: cursed sword + plain amulet → item surcharge on the cursed item's base only → premium 231 G (160 policy base + 50 curse + 16 first insurance + 5 fee)");
    it.todo("long-standing customer's second contract: 3 years, second quote, cursed sword enchantment 7 → premium 160 G (100 + 50 + 30 − 20 loyalty + 10 first insurance − 15 follow-up + 5 fee)");
  });

  describe("claim — reimbursement and deductible", () => {
    it.todo("regular steel sword (enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible), remainingCap 1600 G");
    it.todo("damage to a rune (no enchantment/material), damage 200 G → payout 100 G (full reimbursement minus deductible)");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % high-enchantment clause, then deductible)");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G (full reimbursement clause, then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (both clauses apply, the 50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies at the threshold)");
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 G deductible once per damaged item)");
    it.todo("payout rounding in MHPCO's favor: enchantment-9 sword, damage 901 G → 450.5 − 100 = 350.5 → payout 350 G (rounded down)");
  });

  describe("claim — insurance sum and payout cap", () => {
    it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G; both damaged 500 G each → payout 800 G, remainingCap 3200 G");
    it.todo("cap exhaustion: sword (cap 2000 G), first claim 1500 G → payout 1400 G, remainingCap 600 G; second claim 1500 G → payout 600 G, remainingCap 0 G");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value (premium modifiers do not raise the cap)");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G (block discount affects the premium only, not the insurance sum)");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin, writes results to stdout: 5-year customer, amulet quote → premium 59 G; claim 200 G → payout 100 G, remainingCap 1100 G");
    it.todo("quote with an unknown item type (broomstick) → non-zero exit, error on stderr, no results on stdout");
    it.todo("claim for an item not part of the policy (amulet damaged, only sword insured) → non-zero exit, error on stderr");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → non-zero exit, error on stderr");
    it.todo("damage entry with amount −200 → non-zero exit, error on stderr");
  });
});

